{
"predictors": [
{
"name": "Social Responsibility Score",
"construction": "Use CSR ratings from KLD STATS database. Higher scores indicate more responsible conduct.",
"rationale": "Firms demonstrating social responsibility may be better managed and more forward-thinking, leading to better future performance.",
"higher_returns_for": "High values of the measure"
},
{
"name": "Customer Satisfaction Index",
"construction": "Measure based on the American Customer Satisfaction Index. Higher ratings indicate greater customer satisfaction.",
"rationale": "Firms with high customer satisfaction may have a competitive advantage and better future cash flows.",
"higher_returns_for": "High values of the measure"
},
{
"name": "Patent Quality",
"construction": "Measure based on the number of citations a firm's patents receive. More citations indicate higher quality patents.",
"rationale": "Firms with high-quality patents may be more innovative, leading to better future performance.",
"higher_returns_for": "High values of the measure"
},
{
"name": "Employee Satisfaction",
"construction": "Measure based on employee reviews from websites like Glassdoor.",
"rationale": "Firms with satisfied employees may have better future performance due to higher productivity.",
"higher_returns_for": "High values of the measure"
},
{
"name": "CEO Overconfidence",
"construction": "Measure based on the number of optimistic words in a CEO's public statements. More optimistic words indicate a more overconfident CEO.",
"rationale": "Overconfident CEOs may take on more risky projects, leading to higher future returns.",
"higher_returns_for": "High values of the measure"
},
{
"name": "Online Presence",
"construction": "Measure based on the number of website visits a firm receives. More visits indicate a stronger online presence.",
"rationale": "Firms with a strong online presence may have better future performance due to higher brand recognition.",
"higher_returns_for": "High values of the measure"
},
{
"name": "Supply Chain Efficiency",
"construction": "Measure based on the gap between a firm's inventory turnover and its industry median. Smaller gaps indicate more efficient supply chains.",
"rationale": "Firms with efficient supply chains may have better future performance due to cost savings.",
"higher_returns_for": "Low values of the measure"
},
{
"name": "Earnings Smoothing",
"construction": "Measure based on the standard deviation of a firm's earnings over the past five years. Lower standard deviations indicate more earnings smoothing.",
"rationale": "Firms that smooth earnings may be manipulating financials and could be riskier investments.",
"higher_returns_for": "Low values of the measure"
},
{
"name": "Mergers and Acquisitions Activity",
"construction": "Measure based on the number of M&A transactions a firm has been involved in over the past year.",
"rationale": "Firms with high M&A activity may have higher future returns due to synergies or growth opportunities.",
"higher_returns_for": "High values of the measure"
},
{
"name": "R&D Intensity",
"construction": "Measure based on the ratio of a firm's R&D spending to its total sales.",
"rationale": "Firms with high R&D intensity may have better future performance due to innovation and growth potential.",
"higher_returns_for": "High values of the measure"
}
]
}
